// ── Company Profile Edit ──────────────────────────────────
export function CompanyProfileEditPage() {
  const navigate = useNavigate();

  // State
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");

  const [companyName, setCompanyName] = useState("");
  const [industry, setIndustry] = useState("OTHER");
  const [companySize, setCompanySize] = useState("STARTUP");
  const [wilaya, setWilaya] = useState("alger");
  const [address, setAddress] = useState("");
  const [phone, setPhone] = useState("");
  const [website, setWebsite] = useState("");
  const [bio, setBio] = useState("");

  const [avatarFile, setAvatarFile] = useState(null);
  const [avatarPreview, setAvatarPreview] = useState(null);
  const [verified, setVerified] = useState(false);
  const [profileId, setProfileId] = useState("");

  const fileInputRef = useRef(null);

  // Fetch initial data
  useEffect(() => {
    let cancelled = false;
    const fetchProfile = async () => {
      try {
        const data = await getMyProfileDetails();
        if (cancelled) return;
        if (data) {
          setCompanyName(data.company_name || "");
          setIndustry(data.industry || "OTHER");
          setCompanySize(data.company_size || "STARTUP");
          setWilaya(data.wilaya || "alger");
          setAddress(data.address || "");
          setPhone(data.phone || "");
          setWebsite(data.website || "");
          setBio(data.bio || "");
          setVerified(data.verified || false);
          setProfileId(data.id || "");

          if (data.avatar) {
            setAvatarPreview(data.avatar);
          }
        }
      } catch (err) {
        if (cancelled) return;
        setError(parseApiError(err, "Unable to load company profile."));
      } finally {
        if (!cancelled) setLoading(false);
      }
    };
    fetchProfile();
    return () => {
      cancelled = true;
    };
  }, []);

  const handleAvatarChange = (e) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 2 * 1024 * 1024) {
        setError("Logo image size cannot exceed 2MB.");
        return;
      }
      setAvatarFile(file);
      setAvatarPreview(URL.createObjectURL(file));
      setError("");
    }
  };

  const handleSave = async (e) => {
    e.preventDefault();
    if (!companyName.trim()) {
      setError("Company Name is required.");
      return;
    }
    if (!address.trim()) {
      setError("Address is required.");
      return;
    }

    setSaving(true);
    setError("");
    setSuccess("");

    try {
      // 1. Update text fields (partial update)
      const payload = {
        company_name: companyName.trim(),
        industry,
        company_size: companySize,
        wilaya,
        address: address.trim(),
        phone: phone.trim(),
        website: website.trim(),
        bio: bio.trim(),
      };

      await updateProfile(payload);

      // 2. Update avatar if a new one is selected
      if (avatarFile) {
        const formData = new FormData();
        formData.append("avatar", avatarFile);
        await updateProfile(formData);
      }

      setSuccess("Company profile updated successfully!");
      window.scrollTo({ top: 0, behavior: "smooth" });
      setTimeout(() => {
        navigate("/dashboard/company-profile");
      }, 1500);
    } catch (err) {
      setError(parseApiError(err, "Unable to save company profile changes."));
      window.scrollTo({ top: 0, behavior: "smooth" });
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <p className="text-gray-500 text-sm animate-pulse">Loading company profile...</p>
      </div>
    );
  }

  const getInitials = (name) => {
    if (!name) return "TC";
    const words = name.trim().split(/\s+/).filter(Boolean);
    if (words.length === 0) return "TC";
    if (words.length === 1) return words[0].slice(0, 2).toUpperCase();
    return (words[0][0] + (words[1]?.[0] || "")).toUpperCase();
  };

  const initials = getInitials(companyName);

  return (
    <form onSubmit={handleSave}>
      <div className="flex justify-between items-start mb-6">
        <div>
          <h1 className="font-serif text-3xl font-normal mb-1">Edit Company Profile</h1>
          <p className="text-sm text-gray-400">Changes are visible to all users on the platform.</p>
        </div>
        <div className="flex gap-2">
          <button
            type="button"
            disabled={saving}
            onClick={() => navigate("/dashboard/company-profile")}
            className="px-4 py-2 border border-gray-200 bg-white hover:bg-gray-50 text-gray-700 rounded-full text-sm font-medium transition-all cursor-pointer"
          >
            Cancel
          </button>
          {profileId && (
            <button
              type="button"
              onClick={() => navigate(`/companies/${profileId}`)}
              className="px-4 py-2 border border-gray-200 bg-white hover:bg-gray-50 text-gray-700 rounded-full text-sm font-medium transition-all cursor-pointer"
            >
              Preview public page
            </button>
          )}
          <button
            type="submit"
            disabled={saving}
            className="px-5 py-2 bg-[#3C0713] hover:bg-[#5c0b1e] text-white rounded-full text-sm font-medium transition-all disabled:opacity-50 shadow-sm cursor-pointer"
          >
            {saving ? "Saving Changes..." : "Save Changes"}
          </button>
        </div>
      </div>

      {error && (
        <div className="mb-6 p-4 bg-red-50 border border-red-200 text-red-700 rounded-xl text-sm font-medium shadow-sm flex items-center gap-3 animate-fade-in">
          <span>⚠</span>
          <p>{error}</p>
        </div>
      )}

      {success && (
        <div className="mb-6 p-4 bg-emerald-50 border border-emerald-200 text-emerald-800 rounded-xl text-sm font-medium shadow-sm flex items-center gap-3 animate-fade-in">
          <span className="text-lg">✓</span>
          <p>{success}</p>
        </div>
      )}

      {/* Cover */}
      <div className="linkio-panel overflow-hidden mb-5">
        <div className="h-36 bg-gradient-to-br from-[#3C0713] to-[#25040c] flex items-end justify-end p-3 relative">
          <div className="absolute inset-0 bg-gradient-to-r from-[#3C0713]/80 to-navy/40 mix-blend-multiply" />
        </div>
        <div className="px-6 pb-5 flex flex-col sm:flex-row sm:items-end sm:justify-between gap-4">
          <div className="flex gap-4 items-end -mt-8 relative z-10">
            <div
              onClick={() => fileInputRef.current?.click()}
              className="w-20 h-20 bg-white border-2 border-white rounded-2xl flex items-center justify-center font-bold text-xl shadow-md relative overflow-hidden group cursor-pointer hover:border-[#3C0713] hover:shadow-lg transition-all duration-300"
            >
              {avatarPreview ? (
                <img src={avatarPreview} alt="Company Logo" className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500" />
              ) : (
                <span className="text-gray-700">{initials}</span>
              )}
              <div className="absolute inset-0 bg-black/40 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity duration-300">
                <span className="text-white text-[10px] font-semibold">Edit Logo</span>
              </div>
              {verified && (
                <div className="absolute -bottom-1 -right-1 w-5 h-5 bg-[#3C0713] rounded-full flex items-center justify-center text-white text-[9px] shadow-sm font-bold">
                  ✓
                </div>
              )}
            </div>
            <div>
              <p className="font-semibold text-lg">{companyName || "TechCorp Algérie"}</p>
              <p className="text-sm text-gray-400">
                {verified ? "Verified Company Profile" : "Unverified Company Profile"}
              </p>
            </div>
          </div>
          <button
            type="button"
            onClick={() => fileInputRef.current?.click()}
            className="flex items-center gap-2 text-xs bg-navy text-white hover:bg-navy/95 px-4 py-2 rounded-full font-medium transition-colors shadow-sm self-start sm:self-auto cursor-pointer"
          >
            ✏ Edit Logo
          </button>
          <input
            ref={fileInputRef}
            type="file"
            accept="image/jpeg,image/png"
            className="hidden"
            onChange={handleAvatarChange}
          />
        </div>
      </div>

      {/* Form */}
      <div className="linkio-panel p-6 space-y-6">
        <div>
          <h2 className="font-semibold text-navy text-sm uppercase tracking-wider pb-3 border-b border-gray-100">
            Basic Information
          </h2>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div className="flex flex-col gap-1 mb-2">
            <label className="text-sm font-medium">Company Name *</label>
            <input
              type="text"
              required
              value={companyName}
              onChange={(e) => setCompanyName(e.target.value)}
              className="px-4 py-3 rounded-xl border border-gray-200 bg-cream text-sm outline-none focus:border-navy focus:bg-white w-full transition-all duration-300"
            />
          </div>

          <div className="flex flex-col gap-1 mb-2">
            <label className="text-sm font-medium">Industry / Sector *</label>
            <select
              value={industry}
              onChange={(e) => setIndustry(e.target.value)}
              className="px-4 py-3 rounded-xl border border-gray-200 bg-cream text-sm outline-none focus:border-navy focus:bg-white w-full transition-all duration-300"
            >
              {INDUSTRY_CHOICES.map((choice) => (
                <option key={choice.value} value={choice.value}>
                  {choice.label}
                </option>
              ))}
            </select>
          </div>

          <div className="flex flex-col gap-1 mb-2">
            <label className="text-sm font-medium">Company Size *</label>
            <select
              value={companySize}
              onChange={(e) => setCompanySize(e.target.value)}
              className="px-4 py-3 rounded-xl border border-gray-200 bg-cream text-sm outline-none focus:border-navy focus:bg-white w-full transition-all duration-300"
            >
              {COMPANY_SIZE_CHOICES.map((choice) => (
                <option key={choice.value} value={choice.value}>
                  {choice.label}
                </option>
              ))}
            </select>
          </div>

          <div className="flex flex-col gap-1 mb-2">
            <label className="text-sm font-medium">Headquarters Wilaya *</label>
            <select
              value={wilaya}
              onChange={(e) => setWilaya(e.target.value)}
              className="px-4 py-3 rounded-xl border border-gray-200 bg-cream text-sm outline-none focus:border-navy focus:bg-white w-full transition-all duration-300"
            >
              {WILAYA_CHOICES.map((choice) => (
                <option key={choice.value} value={choice.value}>
                  {choice.label}
                </option>
              ))}
            </select>
          </div>

          <div className="flex flex-col gap-1 mb-2">
            <label className="text-sm font-medium">Address *</label>
            <input
              type="text"
              required
              value={address}
              onChange={(e) => setAddress(e.target.value)}
              className="px-4 py-3 rounded-xl border border-gray-200 bg-cream text-sm outline-none focus:border-navy focus:bg-white w-full transition-all duration-300"
            />
          </div>

          <div className="flex flex-col gap-1 mb-2">
            <label className="text-sm font-medium">Phone Number</label>
            <input
              type="text"
              value={phone}
              onChange={(e) => setPhone(e.target.value)}
              placeholder="e.g. +213555123456"
              className="px-4 py-3 rounded-xl border border-gray-200 bg-cream text-sm outline-none focus:border-navy focus:bg-white w-full transition-all duration-300"
            />
          </div>

          <div className="flex flex-col gap-1 mb-2 md:col-span-2">
            <label className="text-sm font-medium">Website URL</label>
            <input
              type="url"
              value={website}
              onChange={(e) => setWebsite(e.target.value)}
              placeholder="https://yourcompany.dz"
              className="px-4 py-3 rounded-xl border border-gray-200 bg-cream text-sm outline-none focus:border-navy focus:bg-white w-full transition-all duration-300"
            />
          </div>
        </div>

        {/* Action buttons */}
        <div className="flex justify-end gap-3 pt-6 border-t border-gray-100 mt-6">
          <button
            type="button"
            disabled={saving}
            onClick={() => navigate("/dashboard/company-profile")}
            className="px-5 py-2.5 border border-gray-200 bg-white hover:bg-gray-50 text-gray-700 rounded-full text-sm font-medium transition-all cursor-pointer"
          >
            Cancel
          </button>
          <button
            type="submit"
            disabled={saving}
            className="px-8 py-2.5 bg-red hover:bg-red-dark text-white rounded-full text-sm font-semibold disabled:opacity-50 transition-all cursor-pointer shadow-sm"
          >
            {saving ? "Saving Changes..." : "Save Changes"}
          </button>
        </div>

      </div>
    </form>
  );
}

// ── Company Profile View ──────────────────────────────────
export function CompanyProfilePage() {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [company, setCompany] = useState(null);

  useEffect(() => {
    let cancelled = false;
    const fetchProfile = async () => {
      try {
        const data = await getMyProfileDetails();
        if (cancelled) return;
        setCompany(data);
      } catch (err) {
        if (cancelled) return;
        setError(parseApiError(err, "Unable to load company profile."));
      } finally {
        if (!cancelled) setLoading(false);
      }
    };
    fetchProfile();
    return () => {
      cancelled = true;
    };
  }, []);

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <p className="text-gray-500 text-sm animate-pulse">Loading company profile...</p>
      </div>
    );
  }

  if (error || !company) {
    return (
      <div className="bg-white rounded-3xl p-8 border border-gray-150 text-center shadow-sm max-w-xl mx-auto">
        <p className="text-[#3C0713] font-semibold text-lg mb-2">Error</p>
        <p className="text-sm text-gray-500 mb-6">{error || "Company profile not found."}</p>
        <button onClick={() => navigate("/dashboard")} className="px-6 py-2 bg-[#3C0713] text-white rounded-full text-sm cursor-pointer hover:bg-[#5c0b1e] transition-all">
          Go to Dashboard
        </button>
      </div>
    );
  }

  const getInitials = (name) => {
    if (!name) return "TC";
    const words = name.trim().split(/\s+/).filter(Boolean);
    if (words.length === 0) return "TC";
    if (words.length === 1) return words[0].slice(0, 2).toUpperCase();
    return (words[0][0] + (words[1]?.[0] || "")).toUpperCase();
  };

  const initials = getInitials(company.company_name);

  const getIndustryLabel = (ind) => {
    const choices = {
      TECH: "Technology",
      FINANCE: "Finance & Banking",
      WATER: "Water Industry",
      CONSTRUCTION: "Construction & BTP",
      HEALTHCARE: "Healthcare",
      EDUCATION: "Education",
      RETAIL: "Retail & Commerce",
      ENERGY: "Energy & Oil",
      AGRICULTURE: "Agriculture",
      TRANSPORT: "Transport & Logistics",
      OTHER: "Other"
    };
    return choices[ind] || ind || "Other";
  };

  const getCompanySizeLabel = (size) => {
    const choices = {
      STARTUP: "Start-Up (1-10)",
      SMALL: "Small (11-50)",
      MEDIUM: "Medium (51-200)",
      LARGE: "Large (200+)"
    };
    return choices[size] || size || "Medium";
  };

  const getWilayaLabel = (w) => {
    if (!w) return "Alger";
    return w.charAt(0).toUpperCase() + w.slice(1).replace("_", " ");
  };

  return (
    <div>
      <div className="flex justify-between items-start mb-6">
        <div>
          <h1 className="font-serif text-3xl font-normal mb-1">Company Profile</h1>
          <p className="text-sm text-gray-400">This is how your business is displayed on the platform.</p>
        </div>
        <button
          onClick={() => navigate("/dashboard/company-profile/edit")}
          className="px-5 py-2.5 bg-[#3C0713] hover:bg-[#5c0b1e] text-white rounded-full text-sm font-semibold transition-all shadow-sm cursor-pointer flex items-center gap-1.5"
        >
          ✏ Edit Profile
        </button>
      </div>

      {/* Cover */}
      <div className="linkio-panel overflow-hidden mb-6 shadow-sm">
        <div className="h-36 bg-gradient-to-br from-[#3C0713] to-[#25040c] relative flex items-start justify-end p-4">
          <div className="absolute inset-0 bg-gradient-to-r from-[#3C0713]/80 to-navy/30 mix-blend-multiply" />
          {company.verified ? (
            <span className="relative z-10 bg-black/40 border border-white/20 text-white text-xs px-3 py-1.5 rounded-full font-medium">★ Verified Company</span>
          ) : (
            <span className="relative z-10 bg-black/45 border border-white/20 text-white text-xs px-3 py-1.5 rounded-full font-medium">Profile Pending Verification</span>
          )}
        </div>
        <div className="px-6 pb-6">
          <div className="-mt-8 mb-3 relative z-10">
            <div className="w-18 h-18 bg-white border-2 border-white rounded-2xl flex items-center justify-center font-bold text-lg shadow-md overflow-hidden">
              {company.avatar ? (
                <img src={company.avatar} alt="Logo" className="w-full h-full object-cover" />
              ) : (
                <span className="text-gray-700">{initials}</span>
              )}
            </div>
          </div>
          <h2 className="font-serif text-2xl mb-1 text-navy-deep font-semibold">{company.company_name}</h2>
          <p className="text-sm text-gray-500 mb-4 max-w-2xl">{company.bio || "No company description provided yet."}</p>

          <div className="flex gap-5 text-sm text-gray-400 mb-5 flex-wrap">
            <span className="flex items-center gap-1">📍 {getWilayaLabel(company.wilaya)}, {company.address}</span>
            <span className="flex items-center gap-1">🏢 {getIndustryLabel(company.industry)}</span>
            <span className="flex items-center gap-1">👥 {getCompanySizeLabel(company.company_size)} employees</span>
          </div>

          <div className="flex gap-2">
            {company.website && (
              <a
                href={company.website.startsWith("http") ? company.website : `https://${company.website}`}
                target="_blank"
                rel="noreferrer"
                className="px-4 py-2 border border-gray-200 hover:border-[#3C0713] hover:text-[#3C0713] rounded-full text-xs font-semibold transition-all cursor-pointer shadow-sm bg-white"
              >
                Visit Website ↗
              </a>
            )}
            <button
              onClick={() => navigate(`/companies/${company.id}`)}
              className="px-4 py-2 border border-gray-200 hover:border-navy hover:text-navy rounded-full text-xs font-semibold transition-all cursor-pointer shadow-sm bg-white"
            >
              Preview Public Page
            </button>
          </div>
        </div>
      </div>

      {/* Details Section */}
      <div className="grid grid-cols-1 lg:grid-cols-[1fr_300px] gap-6">
        <div className="bg-white rounded-2xl border border-gray-250 p-6 shadow-sm">
          <h3 className="font-semibold mb-4 text-navy-deep text-lg">About the Company</h3>
          <p className="text-sm text-gray-500 leading-relaxed whitespace-pre-wrap">
            {company.bio || "Founded on principles of quality and execution, we represent a premium business identity in Algeria."}
          </p>
        </div>

        <div className="bg-white rounded-2xl border border-gray-250 p-5 shadow-sm h-fit">
          <h4 className="font-semibold mb-4 text-sm text-navy uppercase tracking-wider pb-2 border-b border-gray-100">Business Registry</h4>
          {[
            { l: "Sector", v: getIndustryLabel(company.industry) },
            { l: "Size", v: getCompanySizeLabel(company.company_size) },
            { l: "HQ Location", v: `${getWilayaLabel(company.wilaya)}, Algeria` },
            company.phone && { l: "Phone Number", v: company.phone },
            company.website && { l: "Website", v: company.website, red: true, href: company.website.startsWith("http") ? company.website : `https://${company.website}` },
          ].filter(Boolean).map((r) => (
            <div key={r.l} className="flex justify-between py-2.5 border-b border-gray-50 last:border-0 text-xs">
              <span className="text-gray-400 font-medium">{r.l}</span>
              {r.href ? (
                <a href={r.href} target="_blank" rel="noreferrer" className="text-[#3C0713] font-semibold hover:underline truncate max-w-[170px]">{r.v}</a>
              ) : (
                <span className="font-semibold text-gray-800 truncate max-w-[170px]">{r.v}</span>
              )}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
